The top-20-by-size selection grabbed a spurious (sum) cluster in the seed-0 run — one kept row is nearly orthogonal to every true A1 row (min|cos|=0.022), meaning a genuine neuron got pushed out. I need to diagnose the exact mechanism (is the bad row a sum of two true rows?) before fixing the selection. Let me inspect the bad rows directly:

<tool_call>
{
  "commands": [
    {
      "keystrokes": "cd /app && python3 -c "
import numpy as np, forward as F
S = np.load('/app/stolen_A1.npy'); T = F.A1
Sn=S/np.linalg.norm(S,axis=1,keepdims=True)
Tn=T/np.linalg.norm(T,axis=1,keepdims=True)
# best single-row cos per S row
for i in range(len(S)):
    cs=np.abs(Tn@Sn[i])
    b=int(np.argmax(cs))
    # best sum-direction cos: over all (j,k), direction T[j]+/-T[k]
    bestsum=0.0; bk=None
    for j in range(len(T)):
        for sgn in (1,-1):
            for k in range(len(T)):
                if k==j: continue
                d=T[j]+sgn*T[k]
                if np.linalg.norm(d)<1e-12: continue
                d=d/np.linalg.norm(d)
                c=abs(float(d@Sn[i]))
                if c>bestsum: bestsum=c; bk=(j,sgn,k)
    tag='OK ' if cs[b]>0.99 else 'BAD'
    print(f'row {i:2d}: bestSingle cos={cs[b]:.4f} (T{b}) | bestSum cos={bestsum:.4f} {bk}  [{tag}]')
"
",
      "duration": 3.0
    }
  ]
}
